Object.assign(window.EXAMPLES=window.EXAMPLES||{},{"mir":{"t":"The Mir space station","c":"Mir, meaning ‘peace’ or ‘world’ in Russian, was a Soviet and then Russian space station assembled in orbit from 1986 to 1996, the first modular space station. Over 15 years, about 100 people from 12 countries visited. Cosmonaut Valeri Polyakov spent about 438 consecutive days aboard in 1994–95, still the record for the longest single spaceflight. After the Cold War, American astronauts joined Mir, paving the way for the International Space Station. Mir was deliberately brought down into the Pacific in 2001.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 246\" width=\"640\" height=\"246\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"230\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1986</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Construction begins</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1987–88</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Record year-long stays</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1995</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">US Space Shuttle docks with Mir</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1996</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Final module added</text><circle cx=\"140\" cy=\"202\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"207\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">2001</text><text x=\"156\" y=\"207\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Mir brought down into the Pacific</text></svg>","c":"Milestones of Mir"}]},"tiangong":{"t":"China’s Tiangong space station","c":"Tiangong, meaning ‘heavenly palace’, is China’s permanently crewed space station, in low Earth orbit about 400 kilometres up. Its first module, Tianhe, launched in 2021, and two laboratory modules completed the T-shaped station in 2022. It is about a fifth of the mass of the International Space Station and is normally crewed by three taikonauts, who conduct experiments in biology, physics and materials. China built it after being excluded from the ISS and plans to welcome international astronauts.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 162\" width=\"640\" height=\"162\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"146\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">2021</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Tianhe core module launched</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">2022</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Wentian and Mengtian modules complete the station</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Today</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Crews of three rotate about every six months</text></svg>","c":"Building Tiangong"}]},"chandrayaan":{"t":"India’s Moon missions","c":"Chandrayaan, meaning ‘Moon craft’ in Sanskrit, is the Indian Space Research Organisation’s lunar programme. Chandrayaan-1, launched in 2008, helped confirm the presence of water molecules on the Moon. Chandrayaan-2’s orbiter still studies the Moon, though its lander crashed in 2019. In August 2023 Chandrayaan-3 made India the fourth country to land softly on the Moon and the first near its south pole, where ice may lie in permanently shadowed craters, all on a modest budget.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 162\" width=\"640\" height=\"162\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"146\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#f59e0b\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">2008</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Chandrayaan-1 orbits the Moon; finds signs of water</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#f59e0b\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">2019</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Chandrayaan-2 orbiter succeeds; lander crashes</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#f59e0b\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Aug 2023</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Chandrayaan-3 lands near the south pole</text></svg>","c":"Milestones of Chandrayaan"}]},"philsa":{"t":"The Philippine Space Agency","c":"The Philippine Space Agency, PhilSA, was created by the Philippine Space Act of 2019 to lead the country’s space programme. Even before it existed, Filipino engineers working with Japanese universities built and launched the Diwata microsatellites, from 2016, and later small Maya cube satellites, which photograph the country to help with weather, disasters, farming and mapping. PhilSA plans larger Earth-observation satellites and aims to grow local space skills and industry. Dates of planned missions may change.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 246\" width=\"640\" height=\"246\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"230\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#1d4ed8\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">2016</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Diwata-1: first Filipino-built microsatellite</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#1d4ed8\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">2018</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Diwata-2 launched</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#1d4ed8\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">2019</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Philippine Space Act creates PhilSA</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#1d4ed8\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">2021</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Maya-3 and Maya-4 cube satellites</text><circle cx=\"140\" cy=\"202\" r=\"8\" fill=\"#1d4ed8\"/><text x=\"126\" y=\"207\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Planned</text><text x=\"156\" y=\"207\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">MULA, a larger Earth-observation satellite</text></svg>","c":"Milestones of the Philippine space programme"}]},"artemis":{"t":"The Artemis programme","c":"Artemis is NASA’s programme to return people to the Moon, with international partners including Europe, Japan and Canada, and to prepare for missions to Mars. It is named after the twin sister of Apollo in Greek mythology. Artemis I sent an uncrewed Orion capsule around the Moon in 2022. Later missions plan to fly astronauts around the Moon and then land near the lunar south pole, including the first woman and first person of colour on the Moon, and to build a small station in lunar orbit. Dates of future missions may change.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 204\" width=\"640\" height=\"204\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"188\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#7c3aed\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1972</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Apollo 17: last crewed Moon landing until Artemis</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#7c3aed\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">2022</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Artemis I: uncrewed test around the Moon</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#7c3aed\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Planned</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Artemis II: crew flies around the Moon</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#7c3aed\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Planned</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Artemis III: first woman on the Moon</text></svg>","c":"Artemis missions"}]},"kuiper":{"t":"Beyond Neptune","c":"Beyond Neptune lies the Kuiper belt, a doughnut-shaped region about 30 to 50 times Earth’s distance from the Sun, filled with icy bodies left over from the solar system’s formation, including Pluto, Eris and Arrokoth, visited by New Horizons in 2019. Much farther out, perhaps up to 100,000 times Earth’s distance, the Oort cloud is thought to surround the solar system like a giant shell of trillions of icy objects, the source of long-period comets. No spacecraft has reached it. Distances are in astronomical units, where 1 AU is the Earth–Sun distance.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 224\" width=\"620\" height=\"224\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><text x=\"170\" y=\"31\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Neptune</text><rect x=\"180\" y=\"12\" width=\"119.7\" height=\"28\" rx=\"5\" fill=\"#3b82f6\"/><text x=\"307.7275273114504\" y=\"31\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">30 AU</text><text x=\"170\" y=\"71\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Kuiper belt edge</text><rect x=\"180\" y=\"52\" width=\"130.5\" height=\"28\" rx=\"5\" fill=\"#60a5fa\"/><text x=\"318.4502168762409\" y=\"71\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">about 50 AU</text><text x=\"170\" y=\"111\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Voyager 1 today</text><rect x=\"180\" y=\"92\" width=\"155.5\" height=\"28\" rx=\"5\" fill=\"#94a3b8\"/><text x=\"343.51172397033883\" y=\"111\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">about 165 AU</text><text x=\"170\" y=\"151\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Inner Oort cloud</text><rect x=\"180\" y=\"132\" width=\"207.9\" height=\"28\" rx=\"5\" fill=\"#a78bfa\"/><text x=\"395.88311645709246\" y=\"151\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">about 2,000 AU</text><text x=\"170\" y=\"191\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Outer Oort cloud</text><rect x=\"180\" y=\"172\" width=\"290.0\" height=\"28\" rx=\"5\" fill=\"#7c3aed\"/><text x=\"478\" y=\"191\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">up to 100,000 AU</text></svg>","c":"Distances from the Sun (log scale)"}]},"astrobio":{"t":"What life seems to need","c":"Astrobiology is the study of life in the universe and the search for it beyond Earth. All known life needs liquid water, a source of energy and certain chemical elements such as carbon, hydrogen, nitrogen and oxygen. That guides where scientists look: Mars, which once had rivers and lakes; the hidden oceans of moons such as Europa and Enceladus; and exoplanets in the ‘habitable zone’ of their stars, where water could be liquid. Telescopes are also searching for chemical signs of life in distant planets’ atmospheres. No life beyond Earth has yet been found.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 84\" width=\"610\" height=\"84\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"190\" height=\"64\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Water</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Liquid water, as on Earth</text><rect x=\"210\" y=\"10\" width=\"190\" height=\"64\" rx=\"10\" fill=\"#f59e0b\" fill-opacity=\".2\" stroke=\"#f59e0b\"/><text x=\"224\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Energy</text><text x=\"224\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Sunlight or chemical energy</text><rect x=\"410\" y=\"10\" width=\"190\" height=\"64\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"424\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Chemistry</text><text x=\"424\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Carbon and other key elements</text></svg>","c":"Three ingredients scientists look for"}]},"quasars":{"t":"What a quasar is","c":"Quasars are among the brightest objects in the universe. Each is powered by a supermassive black hole, millions to billions of times the Sun’s mass, at the centre of a distant galaxy. Gas swirling into the black hole forms a disc heated to extreme temperatures, outshining all the stars of its galaxy by hundreds or thousands of times, and some launch jets of particles near the speed of light. Most are billions of light-years away, so we see them as they were when the universe was young. Simplified.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 200\" width=\"620\" height=\"200\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"200\" rx=\"10\" fill=\"#0b1026\"/><circle cx=\"310\" cy=\"100\" r=\"18\" fill=\"#000\" stroke=\"#f59e0b\" stroke-width=\"3\"/><ellipse cx=\"310\" cy=\"100\" rx=\"90\" ry=\"20\" fill=\"none\" stroke=\"#fb923c\" stroke-width=\"8\" opacity=\".7\"/><path d=\"M310,80V10M310,120V190\" stroke=\"#a78bfa\" stroke-width=\"10\" opacity=\".7\"/><text x=\"340\" y=\"24\" text-anchor=\"start\" font-size=\"12\" font-weight=\"800\" fill=\"#e2e8f0\" font-family=\"system-ui,sans-serif\">Jets of particles</text><text x=\"470\" y=\"176\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"#e2e8f0\" font-family=\"system-ui,sans-serif\">Glowing disc of gas around a giant black hole</text></svg>","c":"A quasar’s engine (simplified)"}]},"fruits":{"t":"Where some favourite fruits come from","c":"A fruit, to a botanist, is the part of a flowering plant that holds the seeds, so tomatoes, cucumbers and peppers are fruits too. Many familiar fruits were domesticated long ago and carried around the world by trade: bananas from Southeast Asia and New Guinea, mangoes from South Asia, apples from the mountains of Kazakhstan, citrus from southern China and the Himalayas, and pineapples from South America. The Philippines is among the world’s largest exporters of bananas and pineapples.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 214\" width=\"610\" height=\"214\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"58\" rx=\"10\" fill=\"#facc15\" fill-opacity=\".2\" stroke=\"#facc15\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Banana</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Tropical Asia</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"58\" rx=\"10\" fill=\"#f97316\" fill-opacity=\".2\" stroke=\"#f97316\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Mango</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">South Asia</text><rect x=\"10\" y=\"78\" width=\"290\" height=\"58\" rx=\"10\" fill=\"#dc2626\" fill-opacity=\".2\" stroke=\"#dc2626\"/><text x=\"24\" y=\"106\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Apple</text><text x=\"24\" y=\"126\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Central Asia</text><rect x=\"310\" y=\"78\" width=\"290\" height=\"58\" rx=\"10\" fill=\"#ca8a04\" fill-opacity=\".2\" stroke=\"#ca8a04\"/><text x=\"324\" y=\"106\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Pineapple</text><text x=\"324\" y=\"126\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">South America</text><rect x=\"10\" y=\"146\" width=\"290\" height=\"58\" rx=\"10\" fill=\"#fb923c\" fill-opacity=\".2\" stroke=\"#fb923c\"/><text x=\"24\" y=\"174\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Orange</text><text x=\"24\" y=\"194\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Southern China</text><rect x=\"310\" y=\"146\" width=\"290\" height=\"58\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"324\" y=\"174\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Grapes</text><text x=\"324\" y=\"194\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Western Asia</text></svg>","c":"Six fruits and their regions of origin"}]},"seaweeds":{"t":"What seaweed is used for","c":"Seaweeds are large algae that grow in the sea, in three main groups: green, brown and red. Brown kelps can grow tall underwater forests. Seaweed has been eaten for thousands of years, especially in East Asia, as nori for sushi, kombu for broth and wakame in salads. Substances from red seaweeds, agar and carrageenan, thicken foods from ice cream to jelly; the Philippines is one of the world’s top producers of carrageenan-yielding seaweed. Seaweed farming is growing as a sustainable food source.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 146\" width=\"610\" height=\"146\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"58\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Food</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Nori, kombu, wakame</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"58\" rx=\"10\" fill=\"#ca8a04\" fill-opacity=\".2\" stroke=\"#ca8a04\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Thickeners</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Agar and carrageenan</text><rect x=\"10\" y=\"78\" width=\"290\" height=\"58\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"24\" y=\"106\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Climate</text><text x=\"24\" y=\"126\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Absorbs carbon as it grows</text><rect x=\"310\" y=\"78\" width=\"290\" height=\"58\" rx=\"10\" fill=\"#0891b2\" fill-opacity=\".2\" stroke=\"#0891b2\"/><text x=\"324\" y=\"106\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Habitat</text><text x=\"324\" y=\"126\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Kelp forests shelter sea life</text></svg>","c":"Four ways seaweed matters"}]},"medicinalplants":{"t":"Medicines from plants","c":"People have used plants as medicines for thousands of years, and many modern drugs come from them. Willow bark, used against pain since ancient times, led to aspirin. Foxglove gives digoxin for the heart, the Pacific yew gave the cancer drug paclitaxel, and sweet wormwood, a traditional Chinese remedy, gave artemisinin for malaria, earning Tu Youyou a Nobel Prize in 2015. In the Philippines, herbal medicines such as lagundi for coughs are approved by health authorities. Some plant remedies can be harmful, so medical advice matters.","items":[{"w":1,"s":"<svg viewBox=\"0 0 600 350\" width=\"600\" height=\"350\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"580\" height=\"58\" rx=\"10\" fill=\"#a16207\" fill-opacity=\".2\" stroke=\"#a16207\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Willow bark</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Salicin; led to aspirin</text><rect x=\"10\" y=\"78\" width=\"580\" height=\"58\" rx=\"10\" fill=\"#db2777\" fill-opacity=\".2\" stroke=\"#db2777\"/><text x=\"24\" y=\"106\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Foxglove</text><text x=\"24\" y=\"126\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Digoxin for heart conditions</text><rect x=\"10\" y=\"146\" width=\"580\" height=\"58\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"24\" y=\"174\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Pacific yew</text><text x=\"24\" y=\"194\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Taxol, a cancer drug</text><rect x=\"10\" y=\"214\" width=\"580\" height=\"58\" rx=\"10\" fill=\"#65a30d\" fill-opacity=\".2\" stroke=\"#65a30d\"/><text x=\"24\" y=\"242\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Sweet wormwood</text><text x=\"24\" y=\"262\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Artemisinin for malaria</text><rect x=\"10\" y=\"282\" width=\"580\" height=\"58\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"24\" y=\"310\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Lagundi</text><text x=\"24\" y=\"330\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Philippine remedy for coughs</text></svg>","c":"Five plants and the medicines they gave"}]},"grasses":{"t":"Grasses that feed the world","c":"Grasses are one of the largest and most important plant families, with over 11,000 species, covering grasslands and savannas that make up a large share of Earth’s land. Humans depend on them: rice, wheat and maize, all grasses, provide around half of the calories people eat worldwide, and barley, oats, sorghum, millet and sugarcane are grasses too. Bamboo, the giant among them, is also a grass. Grazing animals that provide meat and milk mostly eat grass.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 214\" width=\"610\" height=\"214\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"58\" rx=\"10\" fill=\"#ca8a04\" fill-opacity=\".2\" stroke=\"#ca8a04\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Rice</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Feeds over half the world</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"58\" rx=\"10\" fill=\"#fde68a\" fill-opacity=\".2\" stroke=\"#fde68a\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Wheat</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Bread, pasta, noodles</text><rect x=\"10\" y=\"78\" width=\"290\" height=\"58\" rx=\"10\" fill=\"#facc15\" fill-opacity=\".2\" stroke=\"#facc15\"/><text x=\"24\" y=\"106\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Maize</text><text x=\"24\" y=\"126\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Most produced grain</text><rect x=\"310\" y=\"78\" width=\"290\" height=\"58\" rx=\"10\" fill=\"#65a30d\" fill-opacity=\".2\" stroke=\"#65a30d\"/><text x=\"324\" y=\"106\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Bamboo</text><text x=\"324\" y=\"126\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">The largest grass</text><rect x=\"10\" y=\"146\" width=\"290\" height=\"58\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"24\" y=\"174\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Sugarcane</text><text x=\"24\" y=\"194\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Most sugar</text><rect x=\"310\" y=\"146\" width=\"290\" height=\"58\" rx=\"10\" fill=\"#22c55e\" fill-opacity=\".2\" stroke=\"#22c55e\"/><text x=\"324\" y=\"174\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Lawn grasses</text><text x=\"324\" y=\"194\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Turf and pasture</text></svg>","c":"Six important grasses"}]},"palms":{"t":"The parts of a palm tree","c":"Palms are a family of about 2,600 species, mostly in the tropics. Unlike most trees, they have no branches and do not form growth rings; their trunks grow from a single bud at the top, crowned by large feather- or fan-shaped leaves. Palms are enormously useful: coconut palms give food, oil, drink, fibre and timber, and are called the ‘tree of life’ in the Philippines, one of the largest coconut producers; date palms feed people in deserts; and oil palms produce the world’s most used vegetable oil. Simplified.","items":[{"s":"<svg viewBox=\"0 0 420 260\" width=\"420\" height=\"260\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:400px;max-width:100%;height:auto\"><rect width=\"420\" height=\"260\" rx=\"10\" fill=\"#e0f2fe\"/><path d=\"M210,250Q200,160 215,60\" fill=\"none\" stroke=\"#a16207\" stroke-width=\"16\"/><path d=\"M215,60Q145.0,40.0 95.0,110.0\" fill=\"none\" stroke=\"#16a34a\" stroke-width=\"8\"/><path d=\"M215,60Q151.9,9.6 106.9,117.8\" fill=\"none\" stroke=\"#16a34a\" stroke-width=\"8\"/><path d=\"M215,60Q171.4,-14.7 140.2,124.1\" fill=\"none\" stroke=\"#16a34a\" stroke-width=\"8\"/><path d=\"M215,60Q199.4,-28.2 188.3,127.5\" fill=\"none\" stroke=\"#16a34a\" stroke-width=\"8\"/><path d=\"M215,60Q230.6,-28.2 241.7,127.5\" fill=\"none\" stroke=\"#16a34a\" stroke-width=\"8\"/><path d=\"M215,60Q258.6,-14.7 289.8,124.1\" fill=\"none\" stroke=\"#16a34a\" stroke-width=\"8\"/><path d=\"M215,60Q278.1,9.6 323.1,117.8\" fill=\"none\" stroke=\"#16a34a\" stroke-width=\"8\"/><path d=\"M215,60Q285.0,40.0 335.0,110.0\" fill=\"none\" stroke=\"#16a34a\" stroke-width=\"8\"/><circle cx=\"200\" cy=\"78\" r=\"10\" fill=\"#78350f\"/><circle cx=\"222\" cy=\"80\" r=\"10\" fill=\"#78350f\"/><circle cx=\"212\" cy=\"92\" r=\"10\" fill=\"#78350f\"/><text x=\"210\" y=\"252\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Coconut palm: no branches, a crown of leaves</text></svg>","c":"A coconut palm, simplified"}]},"vines":{"t":"How climbing plants climb","c":"Climbing plants save energy by using other plants, walls or fences for support instead of building thick trunks, reaching sunlight quickly. They climb in different ways: twiners wrap their whole stems around a support; tendril climbers, such as peas, grapes and bitter gourd, send out coiling threads that grip; root climbers, such as ivy, cling with small roots; and hook climbers, such as rattan palms and roses, hold on with thorns. In tropical forests, huge woody vines called lianas can stretch hundreds of metres.","items":[{"w":1,"s":"<svg viewBox=\"0 0 600 274\" width=\"600\" height=\"274\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"580\" height=\"56\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Twiners</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Stems wind around supports: beans, morning glory</text><rect x=\"10\" y=\"76\" width=\"580\" height=\"56\" rx=\"10\" fill=\"#65a30d\" fill-opacity=\".2\" stroke=\"#65a30d\"/><text x=\"24\" y=\"104\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Tendrils</text><text x=\"24\" y=\"124\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Coiling threads grip: peas, grapes, ampalaya</text><rect x=\"10\" y=\"142\" width=\"580\" height=\"56\" rx=\"10\" fill=\"#4d7c0f\" fill-opacity=\".2\" stroke=\"#4d7c0f\"/><text x=\"24\" y=\"170\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Root climbers</text><text x=\"24\" y=\"190\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Small roots cling: ivy</text><rect x=\"10\" y=\"208\" width=\"580\" height=\"56\" rx=\"10\" fill=\"#a16207\" fill-opacity=\".2\" stroke=\"#a16207\"/><text x=\"24\" y=\"236\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Hook climbers</text><text x=\"24\" y=\"256\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Thorns hook on: rattan, roses</text></svg>","c":"Four climbing methods"}]},"invasiveplants":{"t":"Some troublesome invasive plants","c":"An invasive plant is one brought, deliberately or by accident, to a place where it did not naturally grow, and which then spreads aggressively, crowding out native species, often because it has no natural pests there. Water hyacinth, native to South America, now chokes waterways across Africa and Asia; kudzu from East Asia smothers forests in the southern United States; and Japanese knotweed damages buildings in Europe. Invasive species are among the main causes of biodiversity loss. Checking what you plant and carry helps.","items":[{"w":1,"s":"<svg viewBox=\"0 0 600 274\" width=\"600\" height=\"274\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"580\" height=\"56\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Water hyacinth</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Clogs rivers and lakes, including in the Philippines</text><rect x=\"10\" y=\"76\" width=\"580\" height=\"56\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"24\" y=\"104\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Kudzu</text><text x=\"24\" y=\"124\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">‘The vine that ate the South’ in the US</text><rect x=\"10\" y=\"142\" width=\"580\" height=\"56\" rx=\"10\" fill=\"#f59e0b\" fill-opacity=\".2\" stroke=\"#f59e0b\"/><text x=\"24\" y=\"170\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Lantana</text><text x=\"24\" y=\"190\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Spreads across farmland and forests</text><rect x=\"10\" y=\"208\" width=\"580\" height=\"56\" rx=\"10\" fill=\"#65a30d\" fill-opacity=\".2\" stroke=\"#65a30d\"/><text x=\"24\" y=\"236\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Japanese knotweed</text><text x=\"24\" y=\"256\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Breaks through concrete in Europe</text></svg>","c":"Four invasive plants and the problems they cause"}]},"narra":{"t":"The narra, the national tree","c":"The narra, Pterocarpus indicus, is the national tree of the Philippines. It is a large tree that can grow over 30 metres tall, bursting into fragrant golden-yellow flowers for just a few days each year. Its reddish hardwood is prized for furniture, flooring and carvings and resists termites. Heavy logging has made it scarce in the wild, and it is listed as endangered. The narra grows across Southeast Asia and the Pacific and is often planted along roads for shade. Simplified.","items":[{"s":"<svg viewBox=\"0 0 420 260\" width=\"420\" height=\"260\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:400px;max-width:100%;height:auto\"><rect width=\"420\" height=\"260\" rx=\"10\" fill=\"#ecfccb\"/><rect x=\"196\" y=\"140\" width=\"28\" height=\"110\" fill=\"#78350f\"/><circle cx=\"210\" cy=\"110\" r=\"80\" fill=\"#16a34a\"/><circle cx=\"160\" cy=\"130\" r=\"50\" fill=\"#22c55e\"/><circle cx=\"260\" cy=\"130\" r=\"50\" fill=\"#15803d\"/><circle cx=\"150\" cy=\"60\" r=\"6\" fill=\"#facc15\"/><circle cx=\"187\" cy=\"113\" r=\"6\" fill=\"#facc15\"/><circle cx=\"224\" cy=\"86\" r=\"6\" fill=\"#facc15\"/><circle cx=\"261\" cy=\"139\" r=\"6\" fill=\"#facc15\"/><circle cx=\"178\" cy=\"112\" r=\"6\" fill=\"#facc15\"/><circle cx=\"215\" cy=\"85\" r=\"6\" fill=\"#facc15\"/><circle cx=\"252\" cy=\"138\" r=\"6\" fill=\"#facc15\"/><circle cx=\"169\" cy=\"111\" r=\"6\" fill=\"#facc15\"/><circle cx=\"206\" cy=\"84\" r=\"6\" fill=\"#facc15\"/><circle cx=\"243\" cy=\"137\" r=\"6\" fill=\"#facc15\"/><text x=\"210\" y=\"254\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Golden-yellow flowers each year</text></svg>","c":"A narra tree in bloom, simplified"}]},"sampaguita":{"t":"The sampaguita, the national flower","c":"The sampaguita, Arabian jasmine, was declared the national flower of the Philippines in 1934. Its small white flowers have a sweet, strong scent that is strongest at night. Strung into garlands, sampaguita is sold outside churches and given to welcome visitors, honour graduates and decorate altars. Its name is often said to come from ‘sumpa kita’, ‘I promise you’, linked to a legend of a faithful lover. It is also the national flower of Indonesia, as melati. Simplified.","items":[{"s":"<svg viewBox=\"0 0 420 240\" width=\"420\" height=\"240\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:400px;max-width:100%;height:auto\"><rect width=\"420\" height=\"240\" rx=\"10\" fill=\"#ecfccb\"/><ellipse cx=\"112.0\" cy=\"120.0\" rx=\"10\" ry=\"6\" fill=\"#f8fafc\" stroke=\"#d6d3d1\" transform=\"rotate(0.0 112.0 120.0)\"/><ellipse cx=\"106.0\" cy=\"130.4\" rx=\"10\" ry=\"6\" fill=\"#f8fafc\" stroke=\"#d6d3d1\" transform=\"rotate(60.0 106.0 130.4)\"/><ellipse cx=\"94.0\" cy=\"130.4\" rx=\"10\" ry=\"6\" fill=\"#f8fafc\" stroke=\"#d6d3d1\" transform=\"rotate(120.0 94.0 130.4)\"/><ellipse cx=\"88.0\" cy=\"120.0\" rx=\"10\" ry=\"6\" fill=\"#f8fafc\" stroke=\"#d6d3d1\" transform=\"rotate(180.0 88.0 120.0)\"/><ellipse cx=\"94.0\" cy=\"109.6\" rx=\"10\" ry=\"6\" fill=\"#f8fafc\" stroke=\"#d6d3d1\" transform=\"rotate(240.0 94.0 109.6)\"/><ellipse cx=\"106.0\" cy=\"109.6\" rx=\"10\" ry=\"6\" fill=\"#f8fafc\" stroke=\"#d6d3d1\" transform=\"rotate(300.0 106.0 109.6)\"/><circle cx=\"100\" cy=\"120\" r=\"5\" fill=\"#fef3c7\"/><ellipse cx=\"167.0\" cy=\"150.0\" rx=\"10\" ry=\"6\" fill=\"#f8fafc\" stroke=\"#d6d3d1\" transform=\"rotate(0.0 167.0 150.0)\"/><ellipse cx=\"161.0\" cy=\"160.4\" rx=\"10\" ry=\"6\" fill=\"#f8fafc\" stroke=\"#d6d3d1\" transform=\"rotate(60.0 161.0 160.4)\"/><ellipse cx=\"149.0\" cy=\"160.4\" rx=\"10\" ry=\"6\" fill=\"#f8fafc\" stroke=\"#d6d3d1\" transform=\"rotate(120.0 149.0 160.4)\"/><ellipse cx=\"143.0\" cy=\"150.0\" rx=\"10\" ry=\"6\" fill=\"#f8fafc\" stroke=\"#d6d3d1\" transform=\"rotate(180.0 143.0 150.0)\"/><ellipse cx=\"149.0\" cy=\"139.6\" rx=\"10\" ry=\"6\" fill=\"#f8fafc\" stroke=\"#d6d3d1\" transform=\"rotate(240.0 149.0 139.6)\"/><ellipse cx=\"161.0\" cy=\"139.6\" rx=\"10\" ry=\"6\" fill=\"#f8fafc\" stroke=\"#d6d3d1\" transform=\"rotate(300.0 161.0 139.6)\"/><circle cx=\"155\" cy=\"150\" r=\"5\" fill=\"#fef3c7\"/><ellipse cx=\"222.0\" cy=\"120.0\" rx=\"10\" ry=\"6\" fill=\"#f8fafc\" stroke=\"#d6d3d1\" transform=\"rotate(0.0 222.0 120.0)\"/><ellipse cx=\"216.0\" cy=\"130.4\" rx=\"10\" ry=\"6\" fill=\"#f8fafc\" stroke=\"#d6d3d1\" transform=\"rotate(60.0 216.0 130.4)\"/><ellipse cx=\"204.0\" cy=\"130.4\" rx=\"10\" ry=\"6\" fill=\"#f8fafc\" stroke=\"#d6d3d1\" transform=\"rotate(120.0 204.0 130.4)\"/><ellipse cx=\"198.0\" cy=\"120.0\" rx=\"10\" ry=\"6\" fill=\"#f8fafc\" stroke=\"#d6d3d1\" transform=\"rotate(180.0 198.0 120.0)\"/><ellipse cx=\"204.0\" cy=\"109.6\" rx=\"10\" ry=\"6\" fill=\"#f8fafc\" stroke=\"#d6d3d1\" transform=\"rotate(240.0 204.0 109.6)\"/><ellipse cx=\"216.0\" cy=\"109.6\" rx=\"10\" ry=\"6\" fill=\"#f8fafc\" stroke=\"#d6d3d1\" transform=\"rotate(300.0 216.0 109.6)\"/><circle cx=\"210\" cy=\"120\" r=\"5\" fill=\"#fef3c7\"/><ellipse cx=\"277.0\" cy=\"150.0\" rx=\"10\" ry=\"6\" fill=\"#f8fafc\" stroke=\"#d6d3d1\" transform=\"rotate(0.0 277.0 150.0)\"/><ellipse cx=\"271.0\" cy=\"160.4\" rx=\"10\" ry=\"6\" fill=\"#f8fafc\" stroke=\"#d6d3d1\" transform=\"rotate(60.0 271.0 160.4)\"/><ellipse cx=\"259.0\" cy=\"160.4\" rx=\"10\" ry=\"6\" fill=\"#f8fafc\" stroke=\"#d6d3d1\" transform=\"rotate(120.0 259.0 160.4)\"/><ellipse cx=\"253.0\" cy=\"150.0\" rx=\"10\" ry=\"6\" fill=\"#f8fafc\" stroke=\"#d6d3d1\" transform=\"rotate(180.0 253.0 150.0)\"/><ellipse cx=\"259.0\" cy=\"139.6\" rx=\"10\" ry=\"6\" fill=\"#f8fafc\" stroke=\"#d6d3d1\" transform=\"rotate(240.0 259.0 139.6)\"/><ellipse cx=\"271.0\" cy=\"139.6\" rx=\"10\" ry=\"6\" fill=\"#f8fafc\" stroke=\"#d6d3d1\" transform=\"rotate(300.0 271.0 139.6)\"/><circle cx=\"265\" cy=\"150\" r=\"5\" fill=\"#fef3c7\"/><ellipse cx=\"332.0\" cy=\"120.0\" rx=\"10\" ry=\"6\" fill=\"#f8fafc\" stroke=\"#d6d3d1\" transform=\"rotate(0.0 332.0 120.0)\"/><ellipse cx=\"326.0\" cy=\"130.4\" rx=\"10\" ry=\"6\" fill=\"#f8fafc\" stroke=\"#d6d3d1\" transform=\"rotate(60.0 326.0 130.4)\"/><ellipse cx=\"314.0\" cy=\"130.4\" rx=\"10\" ry=\"6\" fill=\"#f8fafc\" stroke=\"#d6d3d1\" transform=\"rotate(120.0 314.0 130.4)\"/><ellipse cx=\"308.0\" cy=\"120.0\" rx=\"10\" ry=\"6\" fill=\"#f8fafc\" stroke=\"#d6d3d1\" transform=\"rotate(180.0 308.0 120.0)\"/><ellipse cx=\"314.0\" cy=\"109.6\" rx=\"10\" ry=\"6\" fill=\"#f8fafc\" stroke=\"#d6d3d1\" transform=\"rotate(240.0 314.0 109.6)\"/><ellipse cx=\"326.0\" cy=\"109.6\" rx=\"10\" ry=\"6\" fill=\"#f8fafc\" stroke=\"#d6d3d1\" transform=\"rotate(300.0 326.0 109.6)\"/><circle cx=\"320\" cy=\"120\" r=\"5\" fill=\"#fef3c7\"/><text x=\"210\" y=\"226\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Small, white and strongly scented</text></svg>","c":"Sampaguita flowers, simplified"}]},"abaca":{"t":"From abaca plant to fibre","c":"Abaca, also called Manila hemp, is a relative of the banana native to the Philippines, which produces most of the world’s supply. Its leaf stalks yield long, strong fibres that resist salt water, which made abaca the favourite material for ships’ ropes in the age of sail. Today the fibre is pulped into specialty papers for tea bags, coffee filters, cigarette papers and some banknotes, and woven into handicrafts and fabrics. Abaca farming supports many rural families, especially in Bicol and Eastern Visayas. Simplified.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 180\" width=\"620\" height=\"180\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"180\" rx=\"10\" fill=\"#f0fdf4\"/><rect x=\"20\" y=\"50\" width=\"140\" height=\"80\" rx=\"10\" fill=\"#bbf7d0\"/><text x=\"90\" y=\"87\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Abaca plant</text><text x=\"90\" y=\"105\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">a banana relative</text><path d=\"M160,90H182\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M190,90l-10,-6v12z\" fill=\"currentColor\"/><rect x=\"190\" y=\"50\" width=\"120\" height=\"80\" rx=\"10\" fill=\"#fde68a\"/><text x=\"250\" y=\"87\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Stalks stripped</text><text x=\"250\" y=\"105\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">fibres extracted</text><path d=\"M310,90H332\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M340,90l-10,-6v12z\" fill=\"currentColor\"/><rect x=\"340\" y=\"50\" width=\"120\" height=\"80\" rx=\"10\" fill=\"#fef3c7\"/><text x=\"400\" y=\"87\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Dried fibre</text><text x=\"400\" y=\"105\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">strong and long</text><path d=\"M460,90H482\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M490,90l-10,-6v12z\" fill=\"currentColor\"/><rect x=\"490\" y=\"50\" width=\"110\" height=\"80\" rx=\"10\" fill=\"#e5e7eb\"/><text x=\"545\" y=\"87\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Products</text><text x=\"545\" y=\"105\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">rope, tea bags</text></svg>","c":"How abaca becomes fibre"}]},"noodles":{"t":"Noodles around the world","c":"Noodles are eaten across the world in thousands of forms. The oldest known noodles, about 4,000 years old, were found in a bowl at Lajia in northwest China, made from millet. Wheat noodles spread across China and to its neighbours, giving rise to Japanese ramen and udon, Korean naengmyeon and Filipino pancit, whose name comes from Hokkien. Rice noodles are favoured in southern China and Southeast Asia, as in Vietnamese pho and Thai pad thai. Italian pasta developed separately. Long noodles often symbolise long life.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 146\" width=\"610\" height=\"146\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"190\" height=\"58\" rx=\"10\" fill=\"#f59e0b\" fill-opacity=\".2\" stroke=\"#f59e0b\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Ramen</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Japan</text><rect x=\"210\" y=\"10\" width=\"190\" height=\"58\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"224\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Pho</text><text x=\"224\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Vietnam</text><rect x=\"410\" y=\"10\" width=\"190\" height=\"58\" rx=\"10\" fill=\"#ca8a04\" fill-opacity=\".2\" stroke=\"#ca8a04\"/><text x=\"424\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Pancit</text><text x=\"424\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Philippines</text><rect x=\"10\" y=\"78\" width=\"190\" height=\"58\" rx=\"10\" fill=\"#dc2626\" fill-opacity=\".2\" stroke=\"#dc2626\"/><text x=\"24\" y=\"106\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Pad thai</text><text x=\"24\" y=\"126\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Thailand</text><rect x=\"210\" y=\"78\" width=\"190\" height=\"58\" rx=\"10\" fill=\"#ca8a04\" fill-opacity=\".2\" stroke=\"#ca8a04\"/><text x=\"224\" y=\"106\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Pasta</text><text x=\"224\" y=\"126\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Italy</text><rect x=\"410\" y=\"78\" width=\"190\" height=\"58\" rx=\"10\" fill=\"#a16207\" fill-opacity=\".2\" stroke=\"#a16207\"/><text x=\"424\" y=\"106\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Lamian</text><text x=\"424\" y=\"126\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">China (hand-pulled)</text></svg>","c":"Six noodle dishes and where they come from"}]},"ai":{"t":"Kinds of artificial intelligence","c":"Artificial intelligence is the field of building computer systems that do tasks normally needing human intelligence, such as recognising speech, translating languages, spotting patterns and making decisions. Almost all AI today is ‘narrow’, good at specific tasks. Generative AI, which produces text, images and audio, has advanced rapidly since the early 2020s. Artificial general intelligence, matching humans across all tasks, does not yet exist, and experts disagree about when, or whether, it will. AI raises important questions about bias, jobs, privacy and safety.","items":[{"w":1,"s":"<svg viewBox=\"0 0 600 208\" width=\"600\" height=\"208\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"580\" height=\"56\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Narrow AI</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Does one task: translation, image recognition, chess</text><rect x=\"10\" y=\"76\" width=\"580\" height=\"56\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"24\" y=\"104\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Generative AI</text><text x=\"24\" y=\"124\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Creates text, images, audio from patterns</text><rect x=\"10\" y=\"142\" width=\"580\" height=\"56\" rx=\"10\" fill=\"#94a3b8\" fill-opacity=\".2\" stroke=\"#94a3b8\"/><text x=\"24\" y=\"170\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">General AI</text><text x=\"24\" y=\"190\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Human-level across tasks: not yet achieved</text></svg>","c":"Three ways people describe AI"}]},"aieveryday":{"t":"Kinds of artificial intelligence","c":"Artificial intelligence is the field of building computer systems that do tasks normally needing human intelligence, such as recognising speech, translating languages, spotting patterns and making decisions. Almost all AI today is ‘narrow’, good at specific tasks. Generative AI, which produces text, images and audio, has advanced rapidly since the early 2020s. Artificial general intelligence, matching humans across all tasks, does not yet exist, and experts disagree about when, or whether, it will. AI raises important questions about bias, jobs, privacy and safety.","items":[{"w":1,"s":"<svg viewBox=\"0 0 600 208\" width=\"600\" height=\"208\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"580\" height=\"56\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Narrow AI</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Does one task: translation, image recognition, chess</text><rect x=\"10\" y=\"76\" width=\"580\" height=\"56\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"24\" y=\"104\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Generative AI</text><text x=\"24\" y=\"124\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Creates text, images, audio from patterns</text><rect x=\"10\" y=\"142\" width=\"580\" height=\"56\" rx=\"10\" fill=\"#94a3b8\" fill-opacity=\".2\" stroke=\"#94a3b8\"/><text x=\"24\" y=\"170\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">General AI</text><text x=\"24\" y=\"190\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Human-level across tasks: not yet achieved</text></svg>","c":"Three ways people describe AI"}]},"aisafety":{"t":"Concerns in AI safety and ethics","c":"As AI systems grow more capable and widespread, researchers, companies and governments are working on making them fair, safe and accountable. Concerns include biased decisions learned from biased data, such as in hiring or lending; misuse of personal data; convincing fake images and voices; errors stated confidently; effects on jobs; and, looking further ahead, ensuring that powerful systems reliably do what people intend. Responses include testing and evaluation, transparency rules and laws such as the European Union’s AI Act.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 146\" width=\"610\" height=\"146\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"58\" rx=\"10\" fill=\"#dc2626\" fill-opacity=\".2\" stroke=\"#dc2626\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Bias</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Unfair outcomes learned from data</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"58\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Privacy</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Use of personal data</text><rect x=\"10\" y=\"78\" width=\"290\" height=\"58\" rx=\"10\" fill=\"#f59e0b\" fill-opacity=\".2\" stroke=\"#f59e0b\"/><text x=\"24\" y=\"106\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Misinformation</text><text x=\"24\" y=\"126\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Convincing fakes and errors</text><rect x=\"310\" y=\"78\" width=\"290\" height=\"58\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"324\" y=\"106\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Safety and control</text><text x=\"324\" y=\"126\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Systems doing what we intend</text></svg>","c":"Four major areas of concern"}]},"cloud":{"t":"What ‘the cloud’ means","c":"Cloud computing means using computing power, storage and software over the internet instead of on your own device. ‘The cloud’ is really vast data centres full of servers, run by companies such as Amazon, Microsoft and Google, often consuming large amounts of electricity and water for cooling. When you stream a film, back up photos online or use web email, you are using the cloud. Businesses rent cloud capacity rather than buying their own servers, paying only for what they use. Simplified.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 180\" width=\"620\" height=\"180\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"180\" rx=\"10\" fill=\"#f8fafc\"/><rect x=\"20\" y=\"50\" width=\"150\" height=\"80\" rx=\"10\" fill=\"#bfdbfe\"/><text x=\"95\" y=\"87\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Your device</text><text x=\"95\" y=\"105\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">phone or laptop</text><path d=\"M170,90H212\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M220,90l-10,-6v12z\" fill=\"currentColor\"/><rect x=\"220\" y=\"30\" width=\"180\" height=\"120\" rx=\"10\" fill=\"#c7d2fe\"/><text x=\"310\" y=\"87\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">The cloud</text><text x=\"310\" y=\"105\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">huge data centres</text><path d=\"M400,90H442\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M450,90l-10,-6v12z\" fill=\"currentColor\"/><rect x=\"450\" y=\"50\" width=\"150\" height=\"80\" rx=\"10\" fill=\"#bbf7d0\"/><text x=\"525\" y=\"87\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Services</text><text x=\"525\" y=\"105\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">storage, email, video</text></svg>","c":"Using services that run in remote data centres"}]},"streaming":{"t":"How streaming works","c":"Streaming lets you watch or listen to media over the internet while it downloads in small pieces, instead of waiting for a whole file. Services such as Spotify, Netflix and YouTube store content on servers around the world, sending each user a copy from a nearby server and adjusting quality to the connection speed. Streaming has largely replaced CDs, DVDs and downloads, and it changed how artists are paid, usually tiny amounts per play. Recommendation algorithms suggest what to watch or hear next.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 84\" width=\"610\" height=\"84\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"190\" height=\"64\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Streaming</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Plays as it downloads</text><rect x=\"210\" y=\"10\" width=\"190\" height=\"64\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"224\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Subscription</text><text x=\"224\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">A monthly fee</text><rect x=\"410\" y=\"10\" width=\"190\" height=\"64\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"424\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Algorithms</text><text x=\"424\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Suggest what’s next</text></svg>","c":"Three key ideas"}]},"misinformation":{"t":"Checking before you share: SIFT","c":"Misinformation is false or misleading information shared by people who may believe it; disinformation is spread deliberately to deceive. Both travel fast on social media. Researchers recommend the SIFT method developed by digital literacy expert Mike Caulfield: Stop, Investigate the source, Find better coverage, and Trace claims, quotes and images back to their original context. Fact-checking organisations around the world, including in the Philippines, check viral claims. Emotional, surprising posts deserve extra care.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 146\" width=\"610\" height=\"146\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"58\" rx=\"10\" fill=\"#dc2626\" fill-opacity=\".2\" stroke=\"#dc2626\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Stop</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Pause before sharing</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"58\" rx=\"10\" fill=\"#f59e0b\" fill-opacity=\".2\" stroke=\"#f59e0b\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Investigate the source</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Who made it? Are they reliable?</text><rect x=\"10\" y=\"78\" width=\"290\" height=\"58\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"24\" y=\"106\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Find better coverage</text><text x=\"24\" y=\"126\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Do trusted sources report it?</text><rect x=\"310\" y=\"78\" width=\"290\" height=\"58\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"324\" y=\"106\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Trace to the original</text><text x=\"324\" y=\"126\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Find the original context</text></svg>","c":"The four SIFT moves"}]},"deepfakes":{"t":"Spotting deepfakes","c":"Deepfakes are fake videos, images or audio made with AI to show people saying or doing things they never did. They can be used for satire and film, but also for fraud, harassment and political deception, such as cloning a relative’s voice in a scam call. Signs can include odd blinking, mismatched lighting, blurry edges or unnatural speech, though the best fakes are hard to spot. The most reliable defence is checking the source and context, using the SIFT method. Some platforms now label AI-made content.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 146\" width=\"610\" height=\"146\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"58\" rx=\"10\" fill=\"#dc2626\" fill-opacity=\".2\" stroke=\"#dc2626\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Stop</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Pause before sharing</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"58\" rx=\"10\" fill=\"#f59e0b\" fill-opacity=\".2\" stroke=\"#f59e0b\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Investigate the source</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Who made it? Are they reliable?</text><rect x=\"10\" y=\"78\" width=\"290\" height=\"58\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"24\" y=\"106\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Find better coverage</text><text x=\"24\" y=\"126\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Do trusted sources report it?</text><rect x=\"310\" y=\"78\" width=\"290\" height=\"58\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"324\" y=\"106\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Trace to the original</text><text x=\"324\" y=\"126\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Find the original context</text></svg>","c":"The four SIFT moves"}]},"influencers":{"t":"How influencers work","c":"Social media influencers build large followings on platforms such as YouTube, Instagram and TikTok by sharing videos and posts on topics from beauty and gaming to food and education. Many earn money through advertising, sponsored posts, affiliate links and merchandise. Consumer protection rules in many countries require them to clearly disclose paid promotions. Influencer marketing has become a multibillion-dollar industry, while concerns include undisclosed ads, unrealistic images and pressure on young audiences.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 84\" width=\"610\" height=\"84\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"190\" height=\"64\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Followers</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Large online audiences</text><rect x=\"210\" y=\"10\" width=\"190\" height=\"64\" rx=\"10\" fill=\"#f59e0b\" fill-opacity=\".2\" stroke=\"#f59e0b\"/><text x=\"224\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Sponsorship</text><text x=\"224\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Paid ads must be disclosed</text><rect x=\"410\" y=\"10\" width=\"190\" height=\"64\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"424\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Niches</text><text x=\"424\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Beauty, gaming, food…</text></svg>","c":"Three key features"}]},"socialmedia":{"t":"How social media feeds work","c":"Social media platforms such as Facebook, YouTube, Instagram, TikTok and X connect billions of people, letting them share posts, photos and videos. Their feeds are usually ranked by algorithms that learn from what users watch, like and share, aiming to keep them engaged so they can show more ads, which is how most platforms earn money. This can spread useful information and build communities but also amplify misinformation and outrage. The Philippines is among the countries where people spend the most time on social media.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 110\" width=\"620\" height=\"110\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><rect x=\"10\" y=\"20\" width=\"127.5\" height=\"70\" rx=\"10\" fill=\"#bfdbfe\"/><text x=\"73.75\" y=\"60\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">You watch and like</text><path d=\"M137.5,55H159.5\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M167.5,55l-10,-6v12z\" fill=\"currentColor\"/><rect x=\"167.5\" y=\"20\" width=\"127.5\" height=\"70\" rx=\"10\" fill=\"#c7d2fe\"/><text x=\"231.25\" y=\"52\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Algorithm learns</text><text x=\"231.25\" y=\"70\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">your interests</text><path d=\"M295,55H317\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M325,55l-10,-6v12z\" fill=\"currentColor\"/><rect x=\"325\" y=\"20\" width=\"127.5\" height=\"70\" rx=\"10\" fill=\"#fde68a\"/><text x=\"388.75\" y=\"52\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Feed shows more</text><text x=\"388.75\" y=\"70\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">of the same</text><path d=\"M452.5,55H474.5\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M482.5,55l-10,-6v12z\" fill=\"currentColor\"/><rect x=\"482.5\" y=\"20\" width=\"127.5\" height=\"70\" rx=\"10\" fill=\"#fecaca\"/><text x=\"546.25\" y=\"52\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Ads shown</text><text x=\"546.25\" y=\"70\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">the business model</text></svg>","c":"The engagement loop behind social feeds"}]},"podcasts":{"t":"The rise of podcasts","c":"Podcasts are audio, and increasingly video, shows that listeners can download or stream whenever they like. The word, blending iPod and broadcast, was coined in 2004 as people began distributing radio-style shows online through RSS feeds. The true-crime series Serial in 2014 brought podcasts to a mass audience, and there are now millions of shows on every topic. Many are free and supported by ads; some are made by individuals with just a microphone. Videos of podcasts on YouTube have become a major format.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 204\" width=\"640\" height=\"204\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"188\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#7c3aed\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">2004</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">The word ‘podcast’ is coined</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#7c3aed\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">2005</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Apple adds podcasts to iTunes</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#7c3aed\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">2014</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Serial brings podcasts to a mass audience</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#7c3aed\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Today</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Millions of shows; many watched as video</text></svg>","c":"Milestones of podcasting"}]},"wearables":{"t":"Common wearable devices","c":"Wearable technology is electronics worn on the body, usually linked to a phone. Smartwatches and fitness bands track steps, heart rate, sleep and sometimes blood oxygen, and some can detect irregular heart rhythms or falls and call for help. Medical wearables such as continuous glucose monitors help people with diabetes manage blood sugar. Smart glasses and earbuds add displays, cameras and voice assistants. They can encourage healthier habits but raise questions about data privacy and accuracy.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 146\" width=\"610\" height=\"146\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"58\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Smartwatch</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Heart rate, steps, notifications</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"58\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Fitness band</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Activity and sleep</text><rect x=\"10\" y=\"78\" width=\"290\" height=\"58\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"24\" y=\"106\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Smart glasses</text><text x=\"24\" y=\"126\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Displays and cameras</text><rect x=\"310\" y=\"78\" width=\"290\" height=\"58\" rx=\"10\" fill=\"#dc2626\" fill-opacity=\".2\" stroke=\"#dc2626\"/><text x=\"324\" y=\"106\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Continuous glucose monitor</text><text x=\"324\" y=\"126\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Blood sugar for diabetes</text></svg>","c":"Four kinds of wearables"}]},"genetherapy":{"t":"How gene therapy works","c":"Gene therapy treats disease by changing a person’s genes. In a common approach, a modified, harmless virus carries a healthy copy of a gene into cells that have a faulty one, so they can make the missing protein. Newer methods such as CRISPR edit faulty genes directly. Approved gene therapies now treat some inherited forms of blindness, spinal muscular atrophy and sickle cell disease. They can be life-changing but are often extremely expensive, and long-term effects are still being studied. Simplified.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 180\" width=\"620\" height=\"180\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"180\" rx=\"10\" fill=\"#f8fafc\"/><rect x=\"20\" y=\"50\" width=\"150\" height=\"80\" rx=\"10\" fill=\"#fecaca\"/><text x=\"95\" y=\"87\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Faulty gene</text><text x=\"95\" y=\"105\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">causes disease</text><path d=\"M170,90H202\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M210,90l-10,-6v12z\" fill=\"currentColor\"/><rect x=\"210\" y=\"50\" width=\"180\" height=\"80\" rx=\"10\" fill=\"#c7d2fe\"/><text x=\"300\" y=\"87\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Harmless virus carrier</text><text x=\"300\" y=\"105\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">delivers a working gene</text><path d=\"M390,90H422\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M430,90l-10,-6v12z\" fill=\"currentColor\"/><rect x=\"430\" y=\"50\" width=\"170\" height=\"80\" rx=\"10\" fill=\"#bbf7d0\"/><text x=\"515\" y=\"87\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Cells make</text><text x=\"515\" y=\"105\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">the missing protein</text></svg>","c":"Delivering a working gene (simplified)"}]},"telemedicine":{"t":"Seeing a doctor remotely","c":"Telemedicine, or telehealth, uses video calls, phone calls, messaging and apps to provide health care at a distance. Patients can consult doctors without travelling, which helps people in remote areas, such as island communities, and those who find travel difficult. Its use surged during the COVID-19 pandemic. Doctors can review symptoms, give advice and often prescribe medicines, though some conditions still need in-person examinations. Reliable internet and protecting patient privacy are important challenges.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 180\" width=\"620\" height=\"180\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"180\" rx=\"10\" fill=\"#f8fafc\"/><rect x=\"20\" y=\"50\" width=\"130\" height=\"80\" rx=\"10\" fill=\"#bfdbfe\"/><text x=\"85\" y=\"87\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Patient</text><text x=\"85\" y=\"105\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">at home</text><path d=\"M150,90H230\" stroke=\"currentColor\" stroke-width=\"3\" stroke-dasharray=\"6 5\"/><rect x=\"230\" y=\"40\" width=\"160\" height=\"100\" rx=\"10\" fill=\"#c7d2fe\"/><text x=\"310\" y=\"87\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Video or chat</text><text x=\"310\" y=\"105\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">phone, tablet, computer</text><path d=\"M390,90H470\" stroke=\"currentColor\" stroke-width=\"3\" stroke-dasharray=\"6 5\"/><rect x=\"470\" y=\"50\" width=\"130\" height=\"80\" rx=\"10\" fill=\"#bbf7d0\"/><text x=\"535\" y=\"87\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Doctor</text><text x=\"535\" y=\"105\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">anywhere</text></svg>","c":"A remote consultation"}]},"spaceweather":{"t":"How space weather reaches Earth","c":"The Sun constantly blows out a stream of charged particles called the solar wind, and sometimes hurls out huge clouds of plasma in eruptions called coronal mass ejections. Earth’s magnetic field deflects most of these particles, but some are steered down towards the poles, where they make the upper atmosphere glow as auroras: the northern and southern lights. Strong solar storms can disrupt satellites, GPS, radio and power grids, so forecasters watch the Sun around the clock. Simplified, not to scale.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 240\" width=\"620\" height=\"240\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"240\" rx=\"10\" fill=\"#0f172a\"/><circle cx=\"20\" cy=\"120\" r=\"90\" fill=\"#f59e0b\"/><circle cx=\"20\" cy=\"120\" r=\"70\" fill=\"#fbbf24\"/><path d=\"M120,60C260,50 330,84 400,72\" fill=\"none\" stroke=\"#fde68a\" stroke-opacity=\".6\" stroke-width=\"2\"/><path d=\"M120,80C260,70 330,96 400,88\" fill=\"none\" stroke=\"#fde68a\" stroke-opacity=\".6\" stroke-width=\"2\"/><path d=\"M120,100C260,90 330,108 400,104\" fill=\"none\" stroke=\"#fde68a\" stroke-opacity=\".6\" stroke-width=\"2\"/><path d=\"M120,120C260,110 330,120 400,120\" fill=\"none\" stroke=\"#fde68a\" stroke-opacity=\".6\" stroke-width=\"2\"/><path d=\"M120,140C260,130 330,132 400,136\" fill=\"none\" stroke=\"#fde68a\" stroke-opacity=\".6\" stroke-width=\"2\"/><path d=\"M120,160C260,150 330,144 400,152\" fill=\"none\" stroke=\"#fde68a\" stroke-opacity=\".6\" stroke-width=\"2\"/><path d=\"M120,180C260,170 330,156 400,168\" fill=\"none\" stroke=\"#fde68a\" stroke-opacity=\".6\" stroke-width=\"2\"/><path d=\"M560,40C470,40 440,90 440,120C440,150 470,200 560,200\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"3\" stroke-dasharray=\"6 5\"/><circle cx=\"520\" cy=\"120\" r=\"30\" fill=\"#2563eb\"/><path d=\"M505,95Q520,86 535,95\" fill=\"none\" stroke=\"#4ade80\" stroke-width=\"6\"/><path d=\"M505,145Q520,154 535,145\" fill=\"none\" stroke=\"#4ade80\" stroke-width=\"6\"/><text x=\"40\" y=\"226\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#fde68a\" font-family=\"system-ui,sans-serif\">Sun</text><text x=\"250\" y=\"40\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#fde68a\" font-family=\"system-ui,sans-serif\">Solar wind and eruptions</text><text x=\"450\" y=\"224\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"#93c5fd\" font-family=\"system-ui,sans-serif\">Magnetic field</text><text x=\"520\" y=\"170\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"#fff\" font-family=\"system-ui,sans-serif\">Earth</text><text x=\"520\" y=\"30\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"#86efac\" font-family=\"system-ui,sans-serif\">Auroras near the poles</text></svg>","c":"From the Sun to the auroras (simplified, not to scale)"}]},"radioastronomy":{"t":"Why radio telescopes work from the ground","c":"Earth’s atmosphere blocks most kinds of light from space, including gamma rays, X-rays and much of the ultraviolet and infrared. Two ‘windows’ stay open: visible light and a wide band of radio waves. That is why radio telescopes, with their large dish antennas, can observe from the ground, day or night and even through cloud. Radio astronomy discovered pulsars, quasars and the cosmic microwave background, the afterglow of the Big Bang. Linking dishes across the world produced the first image of a black hole in 2019. Simplified.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 155\" width=\"620\" height=\"155\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"20\" width=\"94\" height=\"70\" rx=\"8\" fill=\"#94a3b8\" fill-opacity=\".35\"/><text x=\"57\" y=\"50\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Gamma</text><text x=\"57\" y=\"110\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Blocked</text><rect x=\"110\" y=\"20\" width=\"94\" height=\"70\" rx=\"8\" fill=\"#94a3b8\" fill-opacity=\".35\"/><text x=\"157\" y=\"50\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">X-ray</text><text x=\"157\" y=\"110\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Blocked</text><rect x=\"210\" y=\"20\" width=\"94\" height=\"70\" rx=\"8\" fill=\"#94a3b8\" fill-opacity=\".35\"/><text x=\"257\" y=\"50\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Ultraviolet</text><text x=\"257\" y=\"110\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Mostly blocked</text><rect x=\"310\" y=\"20\" width=\"94\" height=\"70\" rx=\"8\" fill=\"#22c55e\" fill-opacity=\".85\"/><text x=\"357\" y=\"50\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#052e16\" font-family=\"system-ui,sans-serif\">Visible</text><text x=\"357\" y=\"110\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Reaches the ground</text><rect x=\"410\" y=\"20\" width=\"94\" height=\"70\" rx=\"8\" fill=\"#94a3b8\" fill-opacity=\".35\"/><text x=\"457\" y=\"50\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Infrared</text><text x=\"457\" y=\"110\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Mostly blocked</text><rect x=\"510\" y=\"20\" width=\"94\" height=\"70\" rx=\"8\" fill=\"#22c55e\" fill-opacity=\".85\"/><text x=\"557\" y=\"50\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#052e16\" font-family=\"system-ui,sans-serif\">Radio</text><text x=\"557\" y=\"110\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Reaches the ground</text><text x=\"310\" y=\"140\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">The atmosphere’s two ‘windows’ let visible light and radio waves through</text></svg>","c":"Which kinds of light reach the ground (simplified)"}]},"magellanic":{"t":"How far away the Magellanic Clouds are","c":"The Large and Small Magellanic Clouds are two small galaxies orbiting our own Milky Way. They are easy to see with the naked eye from the Southern Hemisphere as faint, misty patches. Indigenous peoples of the south knew them long before European sailors on Magellan’s voyage described them in the 1520s. They are much closer than the Andromeda Galaxy, the nearest large spiral galaxy. In 1987, a supernova in the Large Magellanic Cloud was the closest seen since the invention of the telescope. Distances are approximate.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 144\" width=\"620\" height=\"144\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><text x=\"180\" y=\"31\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Large Magellanic Cloud</text><rect x=\"190\" y=\"12\" width=\"234.8\" height=\"28\" rx=\"5\" fill=\"#7c3aed\"/><text x=\"432.8158532114787\" y=\"31\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">160,000 ly</text><text x=\"180\" y=\"71\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Small Magellanic Cloud</text><rect x=\"190\" y=\"52\" width=\"238.5\" height=\"28\" rx=\"5\" fill=\"#a855f7\"/><text x=\"436.4837396245137\" y=\"71\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">200,000 ly</text><text x=\"180\" y=\"111\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Andromeda Galaxy</text><rect x=\"190\" y=\"92\" width=\"280.0\" height=\"28\" rx=\"5\" fill=\"#2563eb\"/><text x=\"478\" y=\"111\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">2.5 million ly</text></svg>","c":"Distances from Earth in light years (ly; log scale, approximate)"}]},"crabnebula":{"t":"The story of the Crab Nebula","c":"The Crab Nebula is the glowing wreckage of a star that exploded as a supernova. Chinese astronomers recorded the explosion in 1054 as a ‘guest star’ bright enough to see in daylight for about three weeks. The cloud of gas, about 6,500 light years away, is still expanding. At its centre is a pulsar, a city-sized neutron star that spins about 30 times a second, sending out beams of radiation like a lighthouse.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 246\" width=\"640\" height=\"246\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"230\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#7c3aed\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1054</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Chinese astronomers record a new ‘guest star’</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#7c3aed\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1731</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">John Bevis spots the nebula through a telescope</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#7c3aed\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1758</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Charles Messier lists it as M1</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#7c3aed\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1968</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">A pulsar is found at its centre</text><circle cx=\"140\" cy=\"202\" r=\"8\" fill=\"#7c3aed\"/><text x=\"126\" y=\"207\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Today</text><text x=\"156\" y=\"207\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">The pulsar still spins about 30 times a second</text></svg>","c":"From guest star to pulsar"}]},"astronauts":{"t":"Daily life on a space station","c":"Astronauts on the International Space Station live in near-weightlessness as they orbit Earth about every 90 minutes, seeing around 16 sunrises and sunsets a day. They work on experiments, maintain the station and exercise for about two hours daily to slow the loss of bone and muscle. They sleep in sleeping bags fixed to the wall, eat food from sealed packets, and drink water recycled from humidity, sweat and urine. Most stays last about six months.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 232\" width=\"610\" height=\"232\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#f59e0b\" fill-opacity=\".2\" stroke=\"#f59e0b\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">About 16 sunrises a day</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">The station orbits Earth every 90 minutes</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Around 2 hours of exercise</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">To slow bone and muscle loss</text><rect x=\"10\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"24\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Sleeping bags on the wall</text><text x=\"24\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Tied down so they do not float away</text><rect x=\"310\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#0891b2\" fill-opacity=\".2\" stroke=\"#0891b2\"/><text x=\"324\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Water is recycled</text><text x=\"324\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Including sweat and urine</text><rect x=\"10\" y=\"158\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#dc2626\" fill-opacity=\".2\" stroke=\"#dc2626\"/><text x=\"24\" y=\"186\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Food in packets</text><text x=\"24\" y=\"206\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Liquids and crumbs could float off</text><rect x=\"310\" y=\"158\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"324\" y=\"186\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Months at a time</text><text x=\"324\" y=\"206\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Usual stays are about six months</text></svg>","c":"Six facts about living in orbit"}]},"commspace":{"t":"How a reusable rocket booster lands","c":"Commercial spaceflight is run by private companies rather than government space agencies. A key change has been rockets whose first stage, the large lower part, flies back and lands upright to be used again, which has lowered launch costs. Private companies now carry satellites, cargo and astronauts to orbit, and some offer short tourist flights to the edge of space. Simplified.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 110\" width=\"620\" height=\"110\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><rect x=\"10\" y=\"20\" width=\"127.5\" height=\"70\" rx=\"10\" fill=\"#93c5fd\"/><text x=\"73.75\" y=\"52\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Launch</text><text x=\"73.75\" y=\"70\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">engines lift off</text><path d=\"M137.5,55H159.5\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M167.5,55l-10,-6v12z\" fill=\"currentColor\"/><rect x=\"167.5\" y=\"20\" width=\"127.5\" height=\"70\" rx=\"10\" fill=\"#c4b5fd\"/><text x=\"231.25\" y=\"52\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Separate</text><text x=\"231.25\" y=\"70\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">upper stage goes on</text><path d=\"M295,55H317\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M325,55l-10,-6v12z\" fill=\"currentColor\"/><rect x=\"325\" y=\"20\" width=\"127.5\" height=\"70\" rx=\"10\" fill=\"#fde68a\"/><text x=\"388.75\" y=\"52\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Turn back</text><text x=\"388.75\" y=\"70\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">booster flips</text><path d=\"M452.5,55H474.5\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M482.5,55l-10,-6v12z\" fill=\"currentColor\"/><rect x=\"482.5\" y=\"20\" width=\"127.5\" height=\"70\" rx=\"10\" fill=\"#86efac\"/><text x=\"546.25\" y=\"52\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Land</text><text x=\"546.25\" y=\"70\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">on legs, upright</text></svg>","c":"The four stages of a booster’s return (simplified)"}]}});
